from pathlib import Path

ROOT = Path(__file__).resolve().parent
PIPELINE = ROOT / "pipeline.py"
RUN150_TEST = ROOT / "tests" / "test_run150_dual_eyecatch.py"
RUN160_TEST = ROOT / "tests" / "test_run160_public_eyecatch_unification.py"

source = PIPELINE.read_text(encoding="utf-8")
start_marker = "        # Run150: note acquisition and paid-DB decision support are different visual jobs.\n"
end_marker = "        analyzed_at = _analyzed_at_now_iso()\n"
if source.count(start_marker) != 1:
    raise SystemExit(f"Run160 fail-closed: expected exactly one Run150 publication eyecatch marker, found {source.count(start_marker)}")
start = source.index(start_marker)
end = source.index(end_marker, start)
old_block = source[start:end]
if "generated_path = generate_eyecatch_image(" not in old_block:
    raise SystemExit("Run160 fail-closed: legacy Decision Card publication call was not found in the expected block")
if "eyecatch_url = upload_eyecatch_to_github(eyecatch_path, eyecatch_filename)" not in old_block:
    raise SystemExit("Run160 fail-closed: legacy Decision Card upload path was not found in the expected block")

new_block = '''        # Run160: public note delivery and the Notion Eyecatch property use one visual contract.\n        # The Editorial Eyecatch is the single public source of truth.  The legacy Decision Card\n        # renderer remains available only for internal/regression compatibility and is never\n        # invoked from the publication path.  If Editorial generation/upload fails, publish no\n        # image rather than falling back to an internal score card.\n        note_eyecatch_path = ""\n        try:\n            note_output_dir = NOTE_EYECATCH_OUTPUT_DIR if persist_results else os.path.join(REGEN_TEST_OUTPUT_DIR, "eyecatch")\n            os.makedirs(note_output_dir, exist_ok=True)\n            note_eyecatch_filename = f"{_sanitize_filename(source)}__{_sanitize_filename(name)}__note.png"\n            note_eyecatch_path = os.path.join(note_output_dir, note_eyecatch_filename)\n            editorial_category = infer_editorial_category(\n                parsed.get("title_text", ""),\n                parsed.get("what_text", "") or parsed.get("source_summary_text", ""),\n                source,\n            )\n            generate_note_editorial_eyecatch(\n                parsed.get("title_text", "") or name,\n                parsed.get("what_text", "") or parsed.get("source_summary_text", ""),\n                note_eyecatch_path,\n                category=editorial_category,\n            )\n            logger.info(\n                "[NOTE EDITORIAL EYECATCH] %s -> %s category=%s",\n                name, note_eyecatch_path, editorial_category,\n            )\n        except Exception as e:\n            note_eyecatch_path = ""\n            logger.warning("[NOTE EDITORIAL EYECATCH SKIP] %s: %s", name, e)\n\n        eyecatch_url = ""\n        if persist_results:\n            if not note_eyecatch_path:\n                logger.warning(\n                    "[PUBLIC EDITORIAL EYECATCH SKIP] %s: Editorial生成に失敗したため、旧Decision Cardへフォールバックせず画像なしで継続",\n                    name,\n                )\n            else:\n                try:\n                    # Keep the existing public URL namespace for backward compatibility, but upload\n                    # the Editorial bytes.  Notion and note/audit therefore reference the same visual.\n                    eyecatch_filename = f"{_sanitize_filename(name)}.png"\n                    eyecatch_url = upload_eyecatch_to_github(note_eyecatch_path, eyecatch_filename) or ""\n                    if eyecatch_url:\n                        logger.info(\n                            "[PUBLIC EDITORIAL EYECATCH] %s -> %s (source=%s)",\n                            name, eyecatch_url, note_eyecatch_path,\n                        )\n                    else:\n                        logger.warning(\n                            "[PUBLIC EDITORIAL EYECATCH UPLOAD FAILED] %s: 旧Decision Cardへフォールバックしません",\n                            name,\n                        )\n                except Exception as e:\n                    logger.warning(\n                        "[PUBLIC EDITORIAL EYECATCH UPLOAD SKIP] %s: %s / 旧Decision Cardへフォールバックしません",\n                        name, e,\n                    )\n        else:\n            logger.info(\n                f"[REGEN TEST] public Editorial EyecatchのGitHub uploadをスキップ（Editorial画像はArtifactへ生成済み）: {name}"\n            )\n\n'''
source = source[:start] + new_block + source[end:]

# Make the legacy renderer's intent explicit without deleting its regression-tested implementation.
legacy_doc = '    """Generate the approved 1280x670 Decision Score card over the source background.\n'
legacy_replacement = '    """Generate the legacy/internal 1280x670 Decision Score card over the source background.\n\n    Run160: this renderer is retained for internal/regression compatibility only.  The production\n    publication path must use ``generate_note_editorial_eyecatch`` instead.\n'
if source.count(legacy_doc) != 1:
    raise SystemExit(f"Run160 fail-closed: expected one legacy renderer docstring, found {source.count(legacy_doc)}")
source = source.replace(legacy_doc, legacy_replacement, 1)
PIPELINE.write_text(source, encoding="utf-8")

run150 = RUN150_TEST.read_text(encoding="utf-8")
method_start = "    def test_pipeline_keeps_notion_decision_card_and_uses_editorial_for_audit(self):\n"
method_end = "\n\nif __name__ == \"__main__\":\n"
if run150.count(method_start) != 1 or run150.count(method_end) != 1:
    raise SystemExit("Run160 fail-closed: Run150 regression test shape changed unexpectedly")
ms = run150.index(method_start)
me = run150.index(method_end, ms)
replacement_method = '''    def test_pipeline_uses_single_editorial_eyecatch_for_public_and_notion(self):\n        source = (ROOT / "pipeline.py").read_text(encoding="utf-8")\n        self.assertIn("from editorial_eyecatch import", source)\n        self.assertIn("generate_note_editorial_eyecatch(", source)\n        # Legacy Decision Card rendering remains available only as an internal/regression utility.\n        self.assertIn("def generate_eyecatch_image(", source)\n        publication = source.split("# Run160: public note delivery", 1)[1].split("        analyzed_at = _analyzed_at_now_iso()", 1)[0]\n        self.assertNotIn("generate_eyecatch_image(", publication)\n        self.assertNotIn("technical_impact, urgency", publication)\n        # The exact Editorial image generated for note/audit is also the image uploaded for Notion.\n        self.assertIn("eyecatch_url = upload_eyecatch_to_github(note_eyecatch_path, eyecatch_filename)", publication)\n        self.assertIn("旧Decision Cardへフォールバックしません", publication)\n        # Human audit / note delivery continue to receive the Editorial image.\n        self.assertGreaterEqual(source.count("eyecatch_path=note_eyecatch_path"), 2)\n        # Fresh/fixed real-article regression stores the Editorial image inside its existing artifact tree.\n        self.assertIn("os.path.join(REGEN_TEST_OUTPUT_DIR, \\"eyecatch\\")", source)\n'''
run150 = run150[:ms] + replacement_method + run150[me:]
RUN150_TEST.write_text(run150, encoding="utf-8")

RUN160_TEST.write_text('''import unittest\nfrom pathlib import Path\n\n\nROOT = Path(__file__).resolve().parents[1]\n\n\nclass Run160PublicEyecatchUnificationTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        cls.source = (ROOT / "pipeline.py").read_text(encoding="utf-8")\n        marker = "# Run160: public note delivery"\n        cls.publication = cls.source.split(marker, 1)[1].split("        analyzed_at = _analyzed_at_now_iso()", 1)[0]\n\n    def test_editorial_is_single_public_image_source(self):\n        self.assertIn("generate_note_editorial_eyecatch(", self.publication)\n        self.assertIn(\n            "eyecatch_url = upload_eyecatch_to_github(note_eyecatch_path, eyecatch_filename)",\n            self.publication,\n        )\n        self.assertIn("[PUBLIC EDITORIAL EYECATCH]", self.publication)\n\n    def test_legacy_decision_card_is_not_called_by_publication_path(self):\n        self.assertNotIn("generate_eyecatch_image(", self.publication)\n        self.assertNotIn("_extract_eyecatch_score_components", self.publication)\n        self.assertNotIn("generated_path =", self.publication)\n\n    def test_no_fallback_to_internal_score_card(self):\n        self.assertGreaterEqual(self.publication.count("旧Decision Cardへフォールバック"), 3)\n        self.assertIn("if not note_eyecatch_path:", self.publication)\n\n    def test_legacy_renderer_is_retained_only_for_internal_compatibility(self):\n        self.assertIn("def generate_eyecatch_image(", self.source)\n        self.assertIn("legacy/internal 1280x670 Decision Score card", self.source)\n        self.assertIn("publication path must use ``generate_note_editorial_eyecatch``", self.source)\n\n    def test_notion_persistence_consumes_the_editorial_upload_url(self):\n        after = self.source.split("        analyzed_at = _analyzed_at_now_iso()", 1)[1]\n        self.assertIn("parsed[\\\"title_text\\\"], eyecatch_url", after)\n        self.assertIn("title_text, eyecatch_url", self.source)\n\n\nif __name__ == "__main__":\n    unittest.main()\n''', encoding="utf-8")

print("Run160 scoped patch applied successfully")
